INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 8, 'theory', 'Quiz: latches and first memory');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 0, 'What distinguishes a sequential circuit from a combinational one?', '["The output depends not only on the current inputs but also on the state (the past)", "The number of gates", "It works only from a clock", "It always has one output"]', 0, 'State is what a circuit remembers. It is usually stored thanks to feedback: the output returns to the input.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 1, 'NOR-based S-R latch: what happens when S = 1, R = 0?', '["Q = 0", "Q is undefined", "Q = 1", "The latch holds its previous value"]', 2, 'A one on S sets Q. When S = R = 0 the latch holds its value, and S = R = 1 is a forbidden state.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 2, 'Which input state of a NAND-based S-R latch means "hold"?', '["Both inputs 0", "Both inputs 1", "One 0, the other 1", "Any"]', 1, 'With NAND the active level is zero, so two ones change nothing. A zero on one of the inputs sets or resets.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 3, 'What does a D latch do when E = 0?', '["Follows D", "Resets Q", "Sets Q", "Holds the last value regardless of D"]', 3, 'The enable is closed, so the AND gates in front of the S-R latch output zeros, and the latch simply remembers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 8, 4, 'Why are latches replaced with edge-triggered flip-flops?', '["Flip-flops are cheaper", "Latches cannot store data", "A latch is transparent while E is open, so noise passes to the output; a flip-flop captures the value once, on the edge", "Flip-flops need no power"]', 2, 'Writing must happen at one strictly defined moment. The clock signal and edge-triggered flip-flops set that moment for the whole circuit at once.');
